// Package review contains the env-var contract between `entire review` (which
// spawns the agent process) and the lifecycle hook (which adopts the session).
// These names are stable API; renaming any constant is a breaking change.
//
// Design rationale: each spawned agent inherits its own copy of the process
// environment, so multi-tenant correctness (multiple worktrees, multi-agent
// runs) holds by construction — one agent's env vars cannot bleed into
// another agent's session. The lifecycle UserPromptSubmit hook reads these
// env vars to tag the in-flight session as a review session (Kind =
// "agent_review") and records which skills were run.
package review

import (
	"encoding/json"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/provenance"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// Review env vars. Names live in cmd/entire/cli/provenance; review aliases
// them so existing call sites (review.EnvSession, etc.) keep working.
const (
	EnvSession     = provenance.ReviewSession
	EnvAgent       = provenance.ReviewAgent
	EnvSkills      = provenance.ReviewSkills
	EnvPrompt      = provenance.ReviewPrompt
	EnvStartingSHA = provenance.ReviewStartingSHA
)

// EncodeSkills serialises a slice of skill invocation strings to a JSON value
// suitable for storing in the ENTIRE_REVIEW_SKILLS environment variable.
// An empty or nil slice encodes to the literal string "[]".
func EncodeSkills(skills []string) (string, error) {
	if len(skills) == 0 {
		return "[]", nil
	}
	b, err := json.Marshal(skills)
	if err != nil {
		return "", fmt.Errorf("encode skills: %w", err)
	}
	return string(b), nil
}

// DecodeSkills deserialises a value previously produced by EncodeSkills.
// An empty string decodes to a nil slice (no skills configured).
// Any other value that is not valid JSON returns an error.
func DecodeSkills(encoded string) ([]string, error) {
	if encoded == "" {
		return nil, nil
	}
	var skills []string
	if err := json.Unmarshal([]byte(encoded), &skills); err != nil {
		return nil, fmt.Errorf("decode skills: %w", err)
	}
	return skills, nil
}

// AppendReviewEnv adds the ENTIRE_REVIEW_* env vars to base, returning
// the new slice. Used by per-agent reviewers in their AgentReviewer.Start
// implementations to propagate the review-session contract to spawned
// agent processes.
//
// agentName must be the agent's stable registry key (e.g. "claude-code").
// cfg carries skills and the starting SHA. prompt is the full composed
// prompt text (result of ComposeReviewPrompt).
//
// Any pre-existing ENTIRE_REVIEW_* AND ENTIRE_INVESTIGATE_* entries in
// base are stripped before the new values are appended. Stripping review
// entries handles nested invocations and stale inheritance from a parent
// shell — duplicate keys would otherwise have implementation-defined
// precedence. Stripping investigate entries prevents an outer
// `entire investigate` session from mis-tagging a child review session if
// invoked nested (symmetric to AppendInvestigateEnv's behavior).
func AppendReviewEnv(base []string, agentName string, cfg reviewtypes.RunConfig, prompt string) []string {
	skillsJSON, _ := EncodeSkills(cfg.Skills) //nolint:errcheck // EncodeSkills only fails on json.Marshal([]string), which is infallible
	out := make([]string, 0, len(base)+5)
	for _, kv := range base {
		if provenance.IsEntry(kv) {
			continue
		}
		out = append(out, kv)
	}
	return append(out,
		EnvSession+"=1",
		EnvAgent+"="+agentName,
		EnvSkills+"="+skillsJSON,
		EnvPrompt+"="+prompt,
		EnvStartingSHA+"="+cfg.StartingSHA,
	)
}

func tryAdoptEnv(ctx context.Context, state *session.State, expectedAgent string, spec envAdoptionSpec) {
	if state.Kind != "" {
		return
	}
	if envSession := os.Getenv(spec.envSession); envSession != "1" {
		logging.Debug(ctx, spec.kindLabel+" env adoption skipped: "+spec.envSession+" is not \"1\"",
			slog.String("expected_agent", expectedAgent),
			slog.String("observed_value", envSession))
		return
	}
	envAgent := os.Getenv(spec.envAgent)
	if envAgent != expectedAgent {
		logging.Warn(ctx, spec.kindLabel+" env adoption skipped: agent mismatch",
			slog.String("env_agent", envAgent),
			slog.String("hook_agent", expectedAgent))
		return
	}
	startingSHA := os.Getenv(spec.envStartingSHA)
	if startingSHA == "" || state.BaseCommit == "" || startingSHA != state.BaseCommit {
		logging.Warn(ctx, spec.kindLabel+" env adoption skipped: starting SHA mismatch",
			slog.String("env_starting_sha", startingSHA),
			slog.String("state_base_commit", state.BaseCommit))
		return
	}
	spec.apply(ctx, state, envAgent)
}

// adoptReviewEnv tags the session as a review session when ENTIRE_REVIEW_*
// env vars are present on the current process.
func adoptReviewEnv(ctx context.Context, state *session.State, expectedAgent string) {
	tryAdoptEnv(ctx, state, expectedAgent, envAdoptionSpec{
		kindLabel:      "review",
		envSession:     review.EnvSession,
		envAgent:       review.EnvAgent,
		envStartingSHA: review.EnvStartingSHA,
		apply: func(ctx context.Context, state *session.State, envAgent string) {
			skills, err := review.DecodeSkills(os.Getenv(review.EnvSkills))
			if err != nil {
				logging.Warn(ctx, "review env adoption failed: invalid skills JSON",
					slog.String("err", err.Error()))
				return
			}
			state.Kind = session.KindAgentReview
			state.ReviewSkills = skills
			state.ReviewPrompt = os.Getenv(review.EnvPrompt)
			logging.Debug(ctx, "adopted review env",
				slog.String("agent", envAgent),
				slog.Int("skill_count", len(skills)))
		},
	})
}

// adoptInvestigateEnv tags the session as an investigation session when
// ENTIRE_INVESTIGATE_* env vars are present on the current process.
//
// Adoption ordering: adoptReviewEnv runs first; if both env families are
// somehow set on the same process, review wins. Production strips
// ENTIRE_REVIEW_* in AppendInvestigateEnv before spawning each per-turn
// agent process, so this conflict cannot happen for fresh investigate spawns
// — but tryAdoptEnv's short-circuit on state.Kind != "" makes the conflict
// harmless if it ever arises.
func adoptInvestigateEnv(ctx context.Context, state *session.State, expectedAgent string) {
	tryAdoptEnv(ctx, state, expectedAgent, envAdoptionSpec{
		kindLabel:      "investigate",
		envSession:     provenance.InvestigateSession,
		envAgent:       provenance.InvestigateAgent,
		envStartingSHA: provenance.InvestigateStartingSHA,
		apply: func(ctx context.Context, state *session.State, envAgent string) {
			runID := os.Getenv(provenance.InvestigateRunID)
			// Reject empty or malformed RunID — downstream condensation joins
			// session metadata by run ID, and tagging a session with no/invalid
			// ID would leak into checkpoint metadata as junk data.
			if !provenance.IsValidRunID(runID) {
				logging.Warn(ctx, "investigate env adoption skipped: invalid run id",
					slog.String("env_run_id", runID))
				return
			}
			state.Kind = session.KindAgentInvestigate
			state.InvestigateRunID = runID
			state.InvestigateTopic = os.Getenv(provenance.InvestigateTopic)
			logging.Debug(ctx, "adopted investigate env",
				slog.String("agent", envAgent),
				slog.String("run_id", state.InvestigateRunID))
		},
	})
}

// launchableReviewerFor returns the AgentReviewer for agents with a review-runner
// adapter, or nil for agents that are known to Entire but not yet wired into
// `entire review` fan-out. This lives in the cli package to avoid the import cycle:
//
//	review/cmd.go → claudecode/codex/geminicli → review
func launchableReviewerFor(agentName string) reviewtypes.AgentReviewer {
	switch agentName {
	case string(agent.AgentNameClaudeCode):
		return claudecode.NewReviewer()
	case string(agent.AgentNameCodex):
		return codex.NewReviewer()
	case string(agent.AgentNameGemini):
		return geminicli.NewReviewer()
	default:
		return nil
	}
}

