func TestReviewer_ArgvShape(t *testing.T) {
	t.Parallel()
	// Without a model: pi --mode json <prompt>
	cmd := buildReviewCmd(context.Background(), reviewtypes.RunConfig{PerRunPrompt: "extra"})
	if len(cmd.Args) != 4 {
